def conjIntro' (Γ : List F) (b : (φ : F) → φ ∈ Γ → 𝓢 ⊢ φ) : 𝓢 ⊢ ⋀Γ :=
  match Γ with
  | []     => verum
  | [ψ]    => by apply b; simp;
  | ψ :: χ :: Γ => by
    simp;
    exact andIntro (b ψ (by simp)) (conjIntro' _ (by aesop))

